\label{p1}
For a topological space $X$, the following conditions are equivalent:
\begin{enumerate}
\item[{\rm(i)}] 
$X$ is strongly $\varkappa$-Fr\'{e}chet--Urysohn;
\item[{\rm(ii)}]
given any $x\in X$ and any sequence $(U_n)_{n\in\omega}$ of open subsets of $X$ for which 
$x\in \bigcap_{n\in \omega} \stackengine{0pt}{}{\overline{\phantom{U}}}{O}{l}{F}{T}{L}U_n$, there exist a sequence $(x_k)_{k\in\omega}$ converging to $x$ and 
a strictly increasing sequence $(n_k)_{k\in\omega}$ of nonnegative integers such that 
$x_k\in U_{n_k}$ for all $k\in\omega$.
\end{enumerate}

\label{p2}
For a topological space $X$, the following conditions are equivalent:
\begin{enumerate}
\item[{\rm(i)}] 
$X$ is strongly $\varkappa$-Fr\'{e}chet--Urysohn;
\item[{\rm(ii)}] 
$X\times (\omega + 1)$ is $\varkappa$-Fr\'{e}chet--Urysohn;
\item[{\rm(iii)}] 
$X\times [0,1]$ is $\varkappa$-Fr\'{e}chet--Urysohn;
\item[{\rm(iv)}] 
$X\times Y$ is $\varkappa$-Fr\'{e}chet--Urysohn for any first-countable space~$Y$;
\item[{\rm(v)}] 
$X\times Y$ is strongly $\varkappa$-Fr\'{e}chet--Urysohn for any first-countable space~$Y$.
\end{enumerate}

\label{lemma:ind-limit}
Let a space $Z$ be the inductive limit of an increasing sequence $(K_n)_{n\in\omega}$ of its closed subspaces. 
Then the family $\{K_n:n\in\omega\}$ absorbs convergent sequences in~$Z$.

\label{p3}
Suppose that a family $\mathscr F=\{F_n: n\in \omega\}$ of closed subsets of a topological space $X$ absorbs 
convergent sequences in~$X$ and $F_n\subset F_{n+1}$ for all $n\in\omega$.
\begin{enumerate}
\item[{\rm(i)}] 
If $X$ is $\varkappa$-Fr\'{e}chet--Urysohn, then $\bigcup_{n\in\omega}\operatorname{Int} F_n$ is dense in $X$.
\item[{\rm(ii)}] 
If $X$ is strongly $\varkappa$-Fr\'{e}chet--Urysohn, then $\bigcup_{n\in\omega}\operatorname{Int} F_n=X$.
\end{enumerate}

\label{c1}
Let $X$ be a hemicompact space.
\begin{enumerate}
\item[{\rm(i)}] 
If $X$ is $\varkappa$-Fr\'{e}chet--Urysohn, then $X$ has a dense subset of points of local compactness.
\item[{\rm(ii)}] 
If $X$ is strongly $\varkappa$-Fr\'{e}chet--Urysohn, then $X$ is locally compact. 
\end{enumerate}

\label{prop:property_afg}
For any variety $\mathscr{V}$, set $X$, and $g\in F^\mathscr{V}(X)$, the following assertions hold: 
\begin{enumerate}
\item[\rm (i)]
$g\in \langle\operatorname{supp} g\rangle$;
\item[\rm (ii)]
if $A\subset X$ and $g\in\langle  A\rangle$, then $\operatorname{supp} g\subset A$;
\item[\rm (iii)]
if $n$ is the length of $g$ in $F^\mathscr{V}(X)$ and $g=x_1^{\varepsilon_1}x_2^{\varepsilon_2}\dots x_n^{\varepsilon_n}$ 
for some $x_1,\dots,x_n\in X$ and $\varepsilon_1,\dots,\varepsilon_n\in \{-1,1\}$, then $\operatorname{supp} g=\{x_1,\dots,x_n\}$.
\end{enumerate}

\label{prop:afgk}
Let $\mathscr{V}$ be a variety and $X$ be a set. Then, for any $k\in \omega$ and $A\subset X$,
\begin{enumerate}
\item[\rm (i)]
$\langle A\rangle \cap F_k^{\mathscr{V}}(X)=F_k^{\mathscr{V}}(A)$;
\item[\rm (ii)]
if $A$ is finite, then so is $\langle A\rangle \cap F_k^{\mathscr{V}}(X)$.
\end{enumerate}

\label{prop:afgn-finete}
Let $\mathscr{V}$ be a variety and $X$ be a  set.
If $M\subset F^{\mathscr{V}}(X)$ is infinite, then $M^{n+1}\not\subset F_n^{\mathscr{V}}(X)$ for each $n\in\omega$.

\label{new_old_proposition}
For any nondiscrete subgroup $G$ of $F^\mathscr{V}(X)$ and any $n\in \omega$, the intersection $F_n^{\mathscr 
V}(X)\cap G$ is closed and nowhere dense in $G$.

\label{t2}
For any full variety $\mathscr V$ of topological groups and any Tychonoff space $X$, 
every Baire subgroup of $F^\mathscr{V}(X)$ is discrete.

\label{t3}
For any full variety $\mathscr V$ of topological groups and any Tychonoff space $X$, 
every $\varkappa$-Fr\'echet--Urysohn subgroup of $F^\mathscr{V}(X)$ is discrete.

\label{cor:FAB}
 All Baire and all $\varkappa$-Fr\'echet--Urysohn subgroups of \tolerance1000 $F(X)$, $A(X)$, and $B(X)$ are discrete 
for any Tychonoff space~$X$.

\label{cor:FVX-kfu}
For a Tychonoff space $X$ and a full variety $\mathscr{V}$, the following conditions are equivalent: 
\begin{enumerate}
\item[\rm(i)] $X$ is discrete;
\item[\rm(ii)] $F^{\mathscr{V}}(X)$ is discrete;
\item[\rm(iii)] $F^{\mathscr{V}}(X)$ is $\varkappa$-Fr\'echet--Urysohn;
\item[\rm(iv)] $F^{\mathscr{V}}(X)$ is Baire.
\end{enumerate}

\label{q3}
Is it true that every compact topological group contains a dense 
countably tight subspace?

\label{q4}
Is it true that every compact topological group contains a dense 
sequential subspace?
